CREATE OR REPLACE FUNCTION public.hb_checkpoint_position_date()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actual_date date; expected_date date;
BEGIN
 SELECT historical_date INTO actual_date FROM historical_positions
 WHERE id=NEW.position_id AND owner_user_id=NEW.owner_user_id AND account_id=NEW.account_id;
 IF TG_TABLE_NAME='balance_checkpoints' THEN expected_date:=NEW.observed_date;
 ELSE expected_date:=NEW.effective_date; END IF;
 IF actual_date IS DISTINCT FROM expected_date THEN
  RAISE EXCEPTION 'POSITION_DATE_MISMATCH' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.hb_checkpoint_vector()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM allocation_revisions WHERE checkpoint_id=NEW.id AND budget_update_id=NEW.budget_update_id) THEN
 RAISE EXCEPTION 'CHECKPOINT_REQUIRES_COMPLETE_VECTOR' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.hb_close_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p text; c balance_checkpoints; v allocation_revisions; prev month_closings; last_day date;
BEGIN
 SELECT period INTO p FROM budget_periods WHERE id=NEW.period_id;
 last_day:=(to_date(p||'-01','YYYY-MM-DD')+interval '1 month - 1 day')::date;
 IF NEW.historical_through_date<>last_day OR (NEW.closed_at AT TIME ZONE 'Europe/Berlin')::date<=last_day THEN RAISE EXCEPTION 'PERIOD_NOT_ENDED'; END IF;
 IF NEW.version>1 THEN
 SELECT * INTO prev FROM month_closings WHERE id=NEW.previous_version_id;
 IF prev.id IS NULL OR prev.period_id<>NEW.period_id OR prev.version+1<>NEW.version OR jsonb_array_length(NEW.change_evidence_refs)=0 THEN RAISE EXCEPTION 'INVALID_REPORT_CHAIN'; END IF;
 END IF;
 IF NEW.bank_data_completeness='NO_OBSERVATION' THEN
 IF NEW.last_checkpoint_id IS NOT NULL OR NEW.last_bank_observed_date IS NOT NULL OR NEW.last_bank_observed_at IS NOT NULL OR NEW.last_observed_balance_cents IS NOT NULL OR NEW.historical_allocation_revision_id IS NOT NULL OR NEW.allocation_effective_date IS NOT NULL OR NEW.historical_allocated_cents IS NOT NULL OR NEW.historical_free_cents IS NOT NULL OR NEW.end_checkpoint_id IS NOT NULL OR NEW.end_balance_cents IS NOT NULL THEN RAISE EXCEPTION 'NO_OBSERVATION_REQUIRES_NULL'; END IF;
 ELSE
 SELECT * INTO c FROM balance_checkpoints WHERE id=NEW.last_checkpoint_id;
 SELECT * INTO v FROM allocation_revisions WHERE id=NEW.historical_allocation_revision_id;
 IF c.id IS NULL OR v.id IS NULL OR v.checkpoint_id<>c.id OR c.observed_date>last_day OR v.effective_date>last_day OR c.recorded_seq>NEW.evidence_recorded_cutoff_seq OR v.recorded_seq>NEW.evidence_recorded_cutoff_seq OR NEW.last_bank_observed_date IS DISTINCT FROM c.observed_date OR NEW.last_bank_observed_at IS DISTINCT FROM c.observed_at OR NEW.last_observed_balance_cents IS DISTINCT FROM c.balance_cents OR NEW.allocation_effective_date IS DISTINCT FROM v.effective_date OR NEW.historical_allocated_cents IS DISTINCT FROM (SELECT COALESCE(sum(amount_cents),0)::bigint FROM period_allocations WHERE allocation_revision_id=v.id AND period_id=NEW.period_id) OR NEW.historical_free_cents IS NULL THEN RAISE EXCEPTION 'REPORT_SOURCE_MISMATCH'; END IF;
 IF NEW.bank_data_completeness='END_DATE_OBSERVED' THEN
 IF c.observed_date<>last_day OR NEW.end_checkpoint_id IS DISTINCT FROM c.id OR NEW.end_balance_cents IS DISTINCT FROM c.balance_cents THEN RAISE EXCEPTION 'INVALID_END_OBSERVATION'; END IF;
 ELSIF NEW.bank_data_completeness='INCOMPLETE' THEN
 IF c.observed_date=last_day OR NEW.end_checkpoint_id IS NOT NULL OR NEW.end_balance_cents IS NOT NULL THEN RAISE EXCEPTION 'UNKNOWN_END_BALANCE_REQUIRED'; END IF;
 ELSE RAISE EXCEPTION 'INVALID_BANK_COMPLETENESS';
 END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hb_confirmed_vector_match()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p transfer_proposals; actual jsonb; expected jsonb;
BEGIN
 SELECT * INTO p FROM transfer_proposals WHERE id=NEW.proposal_id;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('period',b.period,'amountCents',a.amount_cents::text) ORDER BY b.period),'[]') INTO actual
 FROM period_allocations a JOIN budget_periods b ON b.id=a.period_id WHERE a.allocation_revision_id=NEW.after_allocation_revision_id;
 SELECT COALESCE(jsonb_agg(e ORDER BY e->>'period'),'[]') INTO expected FROM jsonb_array_elements(p.proposal->'input'->'allocations') e;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'CONFIRMED_VECTOR_MISMATCH' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.hb_correction()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior record;
BEGIN
 IF NEW.supersedes_id IS NOT NULL THEN
 EXECUTE format('SELECT logical_fact_id,recorded_seq FROM %I WHERE id=$1 AND owner_user_id=$2 AND account_id=$3',TG_TABLE_NAME) INTO prior USING NEW.supersedes_id,NEW.owner_user_id,NEW.account_id;
 IF prior IS NULL OR prior.logical_fact_id<>NEW.logical_fact_id OR prior.recorded_seq>=NEW.recorded_seq THEN RAISE EXCEPTION 'INVALID_CORRECTION_CHAIN' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hb_funding_link()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d transition_decisions; m jsonb; src uuid; target uuid; p text; t text;
BEGIN
 IF NEW.action<>'FUNDING_TRANSFER' THEN RETURN NULL; END IF;
 SELECT * INTO d FROM transition_decisions WHERE id=NEW.transition_decision_id AND owner_user_id=NEW.owner_user_id AND account_id=NEW.account_id;
 src:=(NEW.before_state->>'fundingPeriodId')::uuid;
 SELECT period INTO p FROM budget_periods WHERE id=src AND account_id=NEW.account_id;
 SELECT period INTO t FROM budget_periods WHERE id=NEW.funding_period_id AND account_id=NEW.account_id;
 m:=d.manifest; target:=(m->>'targetPeriodId')::uuid;
 IF d.id IS NULL OR d.mode NOT IN ('CARRY','FRESH_START') OR d.budget_update_id<>NEW.budget_update_id OR d.recorded_seq<>NEW.recorded_seq OR d.position_id<>NEW.position_id OR target IS DISTINCT FROM NEW.funding_period_id OR p IS NULL OR t IS NULL OR p>=t
  OR (d.mode='CARRY' AND src IS DISTINCT FROM (SELECT source_period_id FROM transfer_proposals WHERE id=d.proposal_id))
  OR NOT COALESCE((m->'sourcePeriodIds') @> jsonb_build_array(src::text),false)
  OR NOT COALESCE((m->'funding') @> jsonb_build_array(jsonb_build_object('decisionId',d.id,'budgetUpdateId',NEW.budget_update_id,'positionId',NEW.position_id,'sourcePeriodId',src,'targetPeriodId',target,'beforeRevisionId',NEW.previous_revision_id,'afterRevisionId',NEW.id)),false)
 THEN RAISE EXCEPTION 'INVALID_FUNDING_DECISION' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.hb_obligation_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p obligation_events; c obligation_events; e obligation_events;
BEGIN
 IF NEW.supersedes_id IS NOT NULL THEN
  SELECT * INTO c FROM obligation_events WHERE id=NEW.supersedes_id;
  IF c.obligation_id IS DISTINCT FROM NEW.obligation_id OR c.action IS DISTINCT FROM NEW.action THEN
   RAISE EXCEPTION 'INVALID_OBLIGATION_CORRECTION' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.action='CREATE' THEN
  IF NEW.previous_revision_id IS NOT NULL OR NEW.before_state IS NOT NULL OR NEW.status<>'UNPAID' OR NEW.outstanding_cents<>NEW.original_cents THEN
   RAISE EXCEPTION 'INVALID_OBLIGATION_CREATE' USING ERRCODE='23514';
  END IF;
 ELSE
  SELECT * INTO p FROM obligation_events WHERE id=NEW.previous_revision_id AND owner_user_id=NEW.owner_user_id AND account_id=NEW.account_id;
  IF p.id IS NULL OR p.obligation_id<>NEW.obligation_id OR p.recorded_seq>NEW.recorded_seq
   OR (p.recorded_seq=NEW.recorded_seq AND p.budget_update_id<>NEW.budget_update_id)
   OR NOT hb_obligation_before(p.position_id,NEW.position_id,NEW.owner_user_id,NEW.account_id,NEW.recorded_seq)
   OR NEW.before_state IS DISTINCT FROM hb_obligation_snapshot(p) THEN
   RAISE EXCEPTION 'INVALID_OBLIGATION_PREDECESSOR' USING ERRCODE='23514';
  END IF;
  IF p.status<>'UNPAID' OR (NEW.action<>'FUNDING_TRANSFER' AND p.funding_period_id<>NEW.funding_period_id) THEN
   RAISE EXCEPTION 'TERMINAL_OR_FUNDING_CHANGE' USING ERRCODE='23514';
  END IF;
  IF NEW.action='FUNDING_TRANSFER' THEN
   IF NEW.supersedes_id IS NOT NULL OR NEW.funding_period_id=p.funding_period_id OR NEW.status<>p.status OR NEW.original_cents<>p.original_cents OR NEW.outstanding_cents<>p.outstanding_cents OR NEW.title<>p.title OR NEW.due_date IS DISTINCT FROM p.due_date OR NEW.is_possible<>p.is_possible OR NEW.reserve_full<>p.reserve_full OR NEW.bank_date IS NOT NULL THEN
    RAISE EXCEPTION 'INVALID_FUNDING_STATE' USING ERRCODE='23514';
   END IF;
  ELSIF NEW.action='AMEND' THEN
   IF NEW.status<>'UNPAID' OR NEW.original_cents::numeric-NEW.outstanding_cents::numeric<>p.original_cents::numeric-p.outstanding_cents::numeric THEN
    RAISE EXCEPTION 'INVALID_OBLIGATION_AMEND' USING ERRCODE='23514';
   END IF;
  ELSE
   IF NEW.original_cents<>p.original_cents OR NEW.title<>p.title OR NEW.due_date IS DISTINCT FROM p.due_date OR NEW.is_possible<>p.is_possible THEN
    RAISE EXCEPTION 'INVALID_OBLIGATION_TRANSITION' USING ERRCODE='23514';
   END IF;
   IF (NEW.action='PARTIAL_SETTLEMENT' AND (NEW.status<>'UNPAID' OR NEW.outstanding_cents>=p.outstanding_cents OR NEW.reserve_full<>p.reserve_full))
    OR (NEW.action='PAID' AND (NEW.status<>'PAID' OR NEW.outstanding_cents<>0))
    OR (NEW.action='CANCELLED' AND (NEW.status<>'CANCELLED' OR NEW.outstanding_cents<>p.outstanding_cents)) THEN
    RAISE EXCEPTION 'INVALID_OBLIGATION_TRANSITION' USING ERRCODE='23514';
   END IF;
  END IF;
 END IF;
 -- Resolve corrections at final batch knowledge; an old UNPAID reference cannot bypass terminal state.
 FOR e IN SELECT t.* FROM obligation_events t WHERE t.obligation_id=NEW.obligation_id AND t.account_id=NEW.account_id AND t.recorded_seq<=NEW.recorded_seq
  AND NOT EXISTS(SELECT 1 FROM obligation_events child WHERE child.supersedes_id=t.id AND child.recorded_seq<=NEW.recorded_seq)
  AND t.status IN ('PAID','CANCELLED')
 LOOP
  IF EXISTS(SELECT 1 FROM obligation_events t WHERE t.obligation_id=e.obligation_id AND t.recorded_seq<=NEW.recorded_seq AND t.id<>e.id
   AND NOT EXISTS(SELECT 1 FROM obligation_events child WHERE child.supersedes_id=t.id AND child.recorded_seq<=NEW.recorded_seq)
   AND NOT hb_obligation_before(t.position_id,e.position_id,NEW.owner_user_id,NEW.account_id,NEW.recorded_seq)) THEN
   RAISE EXCEPTION 'TERMINAL_OBLIGATION' USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.hb_ordering_predecessor()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior ordering_revisions;
BEGIN
 IF NEW.previous_revision_id IS NOT NULL THEN
  SELECT * INTO prior FROM ordering_revisions WHERE id=NEW.previous_revision_id;
  IF prior.id IS NULL OR prior.owner_user_id<>NEW.owner_user_id OR prior.account_id<>NEW.account_id
   OR prior.historical_date<>NEW.historical_date OR prior.recorded_seq>=NEW.recorded_seq THEN
   RAISE EXCEPTION 'INVALID_ORDERING_PREDECESSOR' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.hb_position_before(a uuid, b uuid, owner_id uuid, acct uuid, k bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE x historical_positions; y historical_positions; m jsonb; ai bigint; bi bigint;
BEGIN
 SELECT * INTO x FROM historical_positions WHERE id=a AND owner_user_id=owner_id AND account_id=acct AND recorded_seq<=k;
 SELECT * INTO y FROM historical_positions WHERE id=b AND owner_user_id=owner_id AND account_id=acct AND recorded_seq<=k;
 IF x.id IS NULL OR y.id IS NULL THEN RETURN false; END IF;
 IF x.historical_date<>y.historical_date THEN RETURN x.historical_date<y.historical_date; END IF;
 SELECT manifest INTO m FROM ordering_revisions WHERE owner_user_id=owner_id AND account_id=acct AND historical_date=x.historical_date AND recorded_seq<=k ORDER BY recorded_seq DESC LIMIT 1;
 IF m->>'schemaVersion' IS DISTINCT FROM '1' OR jsonb_typeof(m->'positionIds') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 SELECT min(n) INTO ai FROM jsonb_array_elements_text(m->'positionIds') WITH ORDINALITY AS t(id,n) WHERE id=a::text HAVING count(*)=1;
 SELECT min(n) INTO bi FROM jsonb_array_elements_text(m->'positionIds') WITH ORDINALITY AS t(id,n) WHERE id=b::text HAVING count(*)=1;
 RETURN COALESCE(ai<bi,false);
END $function$

CREATE OR REPLACE FUNCTION public.hb_proposal_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v allocation_revisions; src text; target text;
BEGIN
 SELECT * INTO v FROM allocation_revisions WHERE id=NEW.base_allocation_revision_id;
 SELECT period INTO src FROM budget_periods WHERE id=NEW.source_period_id;
 SELECT period INTO target FROM budget_periods WHERE id=NEW.target_period_id;
 IF NEW.mode IS NULL OR NEW.mode NOT IN ('CARRY','FRESH_START','DEFER') OR NEW.observation_mode IS NULL OR NEW.observation_mode NOT IN ('ACTUAL_CHECK','REUSE_CONFIRMED')
  OR (NEW.mode='FRESH_START' AND NEW.observation_mode<>'ACTUAL_CHECK') OR NEW.expected_revision<0
  OR v.checkpoint_id IS DISTINCT FROM NEW.base_checkpoint_id OR NEW.proposal->>'schemaVersion' IS DISTINCT FROM '1' OR jsonb_typeof(NEW.proposal->'input'->'allocations') IS DISTINCT FROM 'array'
  OR (NEW.mode='CARRY' AND (src IS NULL OR src>=target)) OR (NEW.mode<>'CARRY' AND NEW.source_period_id IS NOT NULL)
 THEN RAISE EXCEPTION 'INVALID_PROPOSAL' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.hb_proposal_outcome()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE pid uuid; p transfer_proposals; d transition_decisions; pos historical_positions; src text; target text;
BEGIN
 pid:=NEW.proposal_id;
 IF pid IS NULL THEN
  RAISE EXCEPTION 'MISSING_PROPOSAL' USING ERRCODE='23514';
 END IF;
 SELECT * INTO p FROM transfer_proposals WHERE id=pid AND owner_user_id=NEW.owner_user_id AND account_id=NEW.account_id;
 IF p.id IS NULL THEN RAISE EXCEPTION 'PROPOSAL_SCOPE' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM transition_decisions WHERE proposal_id=pid) AND EXISTS(SELECT 1 FROM transfer_proposal_cancellations WHERE proposal_id=pid) THEN
  RAISE EXCEPTION 'PROPOSAL_TERMINAL_CONFLICT' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME='transition_decisions' THEN
  d:=NEW;
  SELECT * INTO pos FROM historical_positions WHERE id=d.position_id;
  SELECT period INTO target FROM budget_periods WHERE id=p.target_period_id;
  SELECT period INTO src FROM budget_periods WHERE id=p.source_period_id;
  IF d.mode IS DISTINCT FROM p.mode OR d.observation_mode IS DISTINCT FROM p.observation_mode OR d.before_allocation_revision_id IS DISTINCT FROM p.base_allocation_revision_id
   OR (d.manifest->>'targetPeriodId') IS DISTINCT FROM p.target_period_id::text OR pos.budget_update_id<>d.budget_update_id
   OR d.position_id IS DISTINCT FROM (SELECT position_id FROM allocation_revisions WHERE id=d.after_allocation_revision_id)
   OR (d.observation_mode='REUSE_CONFIRMED' AND p.base_checkpoint_id IS DISTINCT FROM (SELECT checkpoint_id FROM allocation_revisions WHERE id=d.after_allocation_revision_id))
   OR (d.mode='CARRY' AND (src IS NULL OR src>=target OR NOT EXISTS(SELECT 1 FROM budget_transfers WHERE decision_id=d.id)))
   OR (d.mode<>'CARRY' AND EXISTS(SELECT 1 FROM budget_transfers WHERE decision_id=d.id)) THEN
   RAISE EXCEPTION 'PROPOSAL_DECISION_MISMATCH' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.hb_report_head()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c month_closings;
BEGIN
 SELECT * INTO c FROM month_closings WHERE id=NEW.closing_id;
 IF c.period_id IS DISTINCT FROM NEW.period_id OR (TG_OP='INSERT' AND c.version<>1) OR (TG_OP='UPDATE' AND NEW.closing_id<>OLD.closing_id AND c.previous_version_id IS DISTINCT FROM OLD.closing_id) THEN RAISE EXCEPTION 'STALE_REPORT_HEAD'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hb_revision_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE anchor_date date;
BEGIN
 IF NEW.insert_transaction<>pg_current_xact_id()::text THEN RAISE EXCEPTION 'INVALID_INSERT_TRANSACTION'; END IF;
 SELECT observed_date INTO anchor_date FROM balance_checkpoints WHERE id=NEW.checkpoint_id;
 IF anchor_date>NEW.effective_date THEN RAISE EXCEPTION 'ANCHOR_AFTER_VECTOR'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hb_saving_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE p savings_events; c savings_events; e savings_events;
BEGIN
 IF NEW.supersedes_id IS NOT NULL THEN
  SELECT * INTO c FROM savings_events WHERE id=NEW.supersedes_id;
  IF c.savings_id IS DISTINCT FROM NEW.savings_id OR c.action IS DISTINCT FROM NEW.action
   OR c.position_id IS DISTINCT FROM NEW.position_id OR c.effective_date IS DISTINCT FROM NEW.effective_date
   OR c.funding_period_id IS DISTINCT FROM NEW.funding_period_id THEN
   RAISE EXCEPTION 'INVALID_SAVING_CORRECTION' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.action='CREATE' THEN
  IF NEW.previous_revision_id IS NOT NULL OR NEW.before_state IS NOT NULL OR NEW.status<>'ACTIVE' THEN
   RAISE EXCEPTION 'INVALID_SAVING_CREATE' USING ERRCODE='23514';
  END IF;
 ELSE
  SELECT * INTO p FROM savings_events WHERE id=NEW.previous_revision_id AND owner_user_id=NEW.owner_user_id AND account_id=NEW.account_id;
  IF p.id IS NULL OR p.savings_id<>NEW.savings_id OR p.recorded_seq>NEW.recorded_seq
   OR (p.recorded_seq=NEW.recorded_seq AND p.budget_update_id<>NEW.budget_update_id)
   OR NOT hb_position_before(p.position_id,NEW.position_id,NEW.owner_user_id,NEW.account_id,NEW.recorded_seq)
   OR NEW.before_state IS DISTINCT FROM hb_saving_snapshot(p) THEN
   RAISE EXCEPTION 'INVALID_SAVING_PREDECESSOR' USING ERRCODE='23514';
  END IF;
  IF p.status<>'ACTIVE' OR (NEW.action<>'FUNDING_TRANSFER' AND p.funding_period_id<>NEW.funding_period_id) THEN
   RAISE EXCEPTION 'TERMINAL_OR_FUNDING_CHANGE' USING ERRCODE='23514';
  END IF;
  IF NEW.action='FUNDING_TRANSFER' THEN
   IF NEW.supersedes_id IS NOT NULL OR NEW.funding_period_id=p.funding_period_id OR NEW.status<>p.status OR NEW.amount_cents<>p.amount_cents OR NEW.title<>p.title THEN
    RAISE EXCEPTION 'INVALID_FUNDING_STATE' USING ERRCODE='23514';
   END IF;
  ELSIF NEW.action='AMEND' THEN
   IF NEW.amount_cents<>p.amount_cents OR NEW.status<>'ACTIVE' OR NEW.title=p.title THEN
    RAISE EXCEPTION 'INVALID_SAVING_AMEND' USING ERRCODE='23514';
   END IF;
  ELSE
   IF NEW.title<>p.title OR (NEW.action='INCREASE' AND (NEW.status<>'ACTIVE' OR NEW.amount_cents<=p.amount_cents))
    OR (NEW.action='PARTIAL_RELEASE' AND (NEW.status<>'ACTIVE' OR NEW.amount_cents>=p.amount_cents))
    OR (NEW.action='FULL_RELEASE' AND (NEW.status<>'RELEASED' OR NEW.amount_cents<>0)) THEN
    RAISE EXCEPTION 'INVALID_SAVING_TRANSITION' USING ERRCODE='23514';
   END IF;
  END IF;
 END IF;
 FOR e IN SELECT t.* FROM savings_events t WHERE t.savings_id=NEW.savings_id AND t.account_id=NEW.account_id AND t.recorded_seq<=NEW.recorded_seq
  AND NOT EXISTS(SELECT 1 FROM savings_events child WHERE child.supersedes_id=t.id AND child.recorded_seq<=NEW.recorded_seq) AND t.status='RELEASED'
 LOOP
  IF EXISTS(SELECT 1 FROM savings_events t WHERE t.savings_id=e.savings_id AND t.recorded_seq<=NEW.recorded_seq AND t.id<>e.id
   AND NOT EXISTS(SELECT 1 FROM savings_events child WHERE child.supersedes_id=t.id AND child.recorded_seq<=NEW.recorded_seq)
   AND NOT hb_position_before(t.position_id,e.position_id,NEW.owner_user_id,NEW.account_id,NEW.recorded_seq)) THEN
   RAISE EXCEPTION 'TERMINAL_SAVING' USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.hb_transfer_final_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d transition_decisions;
BEGIN
 SELECT * INTO d FROM transition_decisions WHERE id=NEW.decision_id;
 IF COALESCE((SELECT sum(amount_cents) FROM period_allocations WHERE allocation_revision_id=NEW.after_allocation_revision_id AND period_id=NEW.source_period_id),0)<>0
  OR (d.proposal_id IS NOT NULL AND d.proposal_id<>NEW.proposal_id) THEN RAISE EXCEPTION 'INVALID_FINAL_TRANSFER' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.hb_transfer_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE d transition_decisions; p transfer_proposals; before_v allocation_revisions; after_v allocation_revisions; source_amount bigint; target_amount bigint;
BEGIN
 SELECT * INTO d FROM transition_decisions WHERE id=NEW.decision_id;
 SELECT * INTO p FROM transfer_proposals WHERE id=NEW.proposal_id;
 SELECT * INTO before_v FROM allocation_revisions WHERE id=NEW.before_allocation_revision_id;
 SELECT * INTO after_v FROM allocation_revisions WHERE id=NEW.after_allocation_revision_id;
 IF d.mode IS DISTINCT FROM 'CARRY' OR d.budget_update_id IS DISTINCT FROM NEW.budget_update_id OR d.before_allocation_revision_id IS DISTINCT FROM before_v.id OR d.after_allocation_revision_id IS DISTINCT FROM after_v.id OR p.base_allocation_revision_id IS DISTINCT FROM before_v.id OR p.base_checkpoint_id IS DISTINCT FROM before_v.checkpoint_id OR p.source_period_id IS DISTINCT FROM NEW.source_period_id OR p.target_period_id IS DISTINCT FROM NEW.target_period_id THEN RAISE EXCEPTION 'TRANSFER_LINEAGE_MISMATCH'; END IF;
 IF d.observation_mode='REUSE_CONFIRMED' THEN
 IF before_v.checkpoint_id IS DISTINCT FROM after_v.checkpoint_id THEN RAISE EXCEPTION 'TRANSFER_CHANGED_CHECKPOINT'; END IF;
 SELECT COALESCE(sum(amount_cents),0)::bigint INTO source_amount FROM period_allocations WHERE allocation_revision_id=before_v.id AND period_id=NEW.source_period_id;
 SELECT COALESCE(sum(amount_cents),0)::bigint INTO target_amount FROM period_allocations WHERE allocation_revision_id=before_v.id AND period_id=NEW.target_period_id;
 IF EXISTS (
 SELECT 1 FROM (
 SELECT period_id,sum(CASE WHEN allocation_revision_id=after_v.id THEN amount_cents ELSE -amount_cents END) AS delta
 FROM period_allocations WHERE allocation_revision_id IN (before_v.id,after_v.id) GROUP BY period_id
 ) a WHERE a.delta<>CASE WHEN a.period_id=NEW.source_period_id THEN -source_amount WHEN a.period_id=NEW.target_period_id THEN source_amount ELSE 0 END
 ) THEN RAISE EXCEPTION 'TRANSFER_VECTOR_MISMATCH'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hb_transition_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v allocation_revisions; c balance_checkpoints;
BEGIN
 SELECT * INTO v FROM allocation_revisions WHERE id=NEW.after_allocation_revision_id;
 SELECT * INTO c FROM balance_checkpoints WHERE id=v.checkpoint_id;
 IF v.budget_update_id IS DISTINCT FROM NEW.budget_update_id OR
   (NEW.observation_mode='ACTUAL_CHECK' AND c.budget_update_id IS DISTINCT FROM NEW.budget_update_id) OR
   (NEW.observation_mode='REUSE_CONFIRMED' AND c.budget_update_id=NEW.budget_update_id)
 THEN RAISE EXCEPTION 'TRANSITION_OBSERVATION_MISMATCH'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hb_vector_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE created_tx text;
BEGIN
 SELECT insert_transaction INTO created_tx FROM allocation_revisions WHERE id=NEW.allocation_revision_id;
 IF created_tx IS DISTINCT FROM pg_current_xact_id()::text THEN RAISE EXCEPTION 'SEALED_ALLOCATION_REVISION' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.hb_vector_sum()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE rid uuid; expected bigint; actual numeric;
BEGIN
 IF TG_TABLE_NAME='period_allocations' THEN rid:=NEW.allocation_revision_id; ELSE rid:=NEW.id; END IF;
 SELECT c.balance_cents INTO expected FROM allocation_revisions r JOIN balance_checkpoints c ON c.id=r.checkpoint_id WHERE r.id=rid;
 SELECT COALESCE(sum(amount_cents),0) INTO actual FROM period_allocations WHERE allocation_revision_id=rid;
 IF expected IS NULL OR actual<>expected THEN RAISE EXCEPTION 'ALLOCATION_SUM_MISMATCH' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$
